import {selectBacklogRun,saveBacklogRun} from './backfill-state.js';
import {pageTitle} from './pageview.js';
import {categories,products,personas,productProperties,money} from './catalog.js';
import {icon,art} from './art.js';
import {storage,config,identity,saveIdentity,uuid} from './storage.js';
import {startTelemetry,track,identify,newAnonymous,sdkStatus,eventLog} from './telemetry.js';
import {totals,validatePayment,paymentOutcome} from './commerce.js';
import {createRun,generateBacklog,uploadBacklog,projectFingerprint} from './backlog.js';
const $=s=>document.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const PROJECT_AI_CONTEXT="This is an e-commerce site selling electronics with a loyalty programme.\n\nThe checkout process consists of the following steps:\n\n* Product Viewed\n* Product Added to Cart\n* Cart Viewed\n* Checkout Step Completed\n* Order Completed";
const findProduct=id=>products.find(p=>p.id===id);
let recordViews=true;
const viewTrack=(...args)=>{if(recordViews)track(...args);};
let activePersona=personas.find(p=>p.id===identity.userId);
let cart=[],wishlist=[],coupon='',shipping='standard';
let checkout={step:1,delivery:{},attempt:0,busy:false};
let settingsTab='start',showAuto=true,uploadController=null,uploadBusy=false,backlogMessage='';
const currentProject=config.apiKey?await projectFingerprint(config.apiKey,config.region):null;
function makeBacklogRun(project=currentProject){return {...createRun(Date.now(),`spring-tech-${uuid().slice(0,8)}`,new URL('./',location.href.split('#')[0]).href),...(project?{project}:{})};}
let run=selectBacklogRun(storage,currentProject,makeBacklogRun),generated=null;
function shopKey(){return `shop:${identity.userId||identity.deviceId}`;}
function readShop(){const saved=storage.get(shopKey(),{});cart=(saved.cart||[]).filter(row=>findProduct(row.id)&&Number.isInteger(row.qty)&&row.qty>0).map(row=>({...row,qty:Math.min(findProduct(row.id).stock,row.qty,20)}));wishlist=saved.wishlist||[];coupon=saved.coupon||'';}
function saveShop(){storage.set(shopKey(),{cart,wishlist,coupon});}
readShop();
function toast(message){const el=document.createElement('div');el.className='toast';el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),5000);}
function go(path){if(location.hash===`#${path}`)render(true);else location.hash=path;}
function routeInfo(){const [path,query='']=(location.hash.slice(1)||'/').split('?');return {path,params:new URLSearchParams(query)};}
function pageShell(title,subtitle,body){return `<div class="container"><div class="breadcrumb"><a href="#/">Home</a><span>›</span><span>${esc(title)}</span></div><div class="page-heading"><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${body}</div>`;}
function renderHeader(){const count=cart.reduce((sum,x)=>sum+x.qty,0);$('#header').innerHTML=`<div class="header-main"><a class="brand" href="./" aria-label="Amplitronics home">Ampli<span>tronics</span><span style="font-size:12px;vertical-align:top;margin-left:2px">✳</span></a><form class="search" id="search-form" role="search">${icon('search')}<label class="visually-hidden" for="site-search">Search products</label><input id="site-search" name="query" placeholder="Find your next favourite thing…" autocomplete="off"><button aria-label="Search">${icon('arrow')}</button></form><div class="header-actions"><a href="#/stores" class="header-action location">${icon('pin')}<span><small>Your store</small>Sydney CBD</span></a><a href="#/account" class="header-action" aria-label="Your account">${icon('user')}<span class="account-label"><small>${activePersona?'Welcome back':'Hello, good to see you'}</small>${activePersona?esc(activePersona.name.split(' ')[0]):'Sign in'}</span></a><a href="#/cart" class="header-action" aria-label="Cart, ${count} items"><span class="cart-icon">${icon('cart')}<span class="count">${count}</span></span></a></div></div><nav aria-label="Main navigation"><a href="#/shop"><b>☰ &nbsp; Shop all</b></a>${categories.slice(0,5).map(c=>`<a href="#/shop?category=${c.id}">${c.name}</a>`).join('')}<div class="nav-end"><a href="#/rewards">Amp Rewards</a><a href="#/help">Help & support</a></div></nav>`;}
function renderFooter(){$('#footer').innerHTML=`<div class="footer-main"><div class="footer-brand"><a class="brand" href="./">Ampli<span>tronics</span>✳</a><p>Good tech. Great energy.<br>A little upgrade for your everyday.</p><p>Fictional workshop retailer. No real payments, products or accounts.</p></div><div><strong>Find your thing</strong>${categories.slice(0,4).map(c=>`<a href="#/shop?category=${c.id}">${c.name}</a>`).join('')}</div><div><strong>Here to help</strong><a href="#/help">Help & support</a><a href="#/stores">Find a store</a><a href="#/account">Your orders</a><a href="#/wishlist">Your wishlist</a></div><div><strong>A little more Ampli</strong><a href="#/rewards">Amp Rewards</a><a href="#/workshop">Participant quick-start ↗</a><a href="./README.md">Implementation notes</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Amplitronics. Made for curious minds.</span><span>Prices in AUD, including simulated GST. &nbsp; A practitioner workshop experience.</span></div>`;}
function productCard(p){return `<article class="product-card"><a href="#/product/${p.id}" class="product-visual" aria-label="View ${p.name}"><span class="badge ${p.badge.startsWith('SAVE')?'save-badge':''}">${p.badge}</span>${art(p.art,p.color)}</a><button class="wish-button ${wishlist.includes(p.id)?'active':''}" data-action="wish" data-id="${p.id}" aria-label="${wishlist.includes(p.id)?'Remove':'Save'} ${p.name} ${wishlist.includes(p.id)?'from':'to'} wishlist" aria-pressed="${wishlist.includes(p.id)}">${icon('heart')}</button><div class="product-info"><div class="product-brand">${p.brand}</div><a href="#/product/${p.id}"><h3>${p.name}</h3></a><div class="product-subtitle">${p.subtitle}</div><div class="rating"><span class="stars" aria-label="${p.rating} out of 5 stars">★★★★★</span> ${p.rating} <span class="review-count">(${p.reviews})</span></div><div class="price-row"><span class="price">${money(p.price)}</span><span class="old-price">${money(p.was)}</span></div><div class="product-bottom"><span class="in-stock">In stock. Ready to go.</span><button class="add-button" data-action="add" data-id="${p.id}" aria-label="Add ${p.name} to cart">+ Add to cart</button></div></div></article>`;}
function home(){return `<div class="sale-strip">${icon('bolt')} <b>SPRING TECH SALE IS ON</b> Your next upgrade, for a little less. &nbsp; <a href="#/shop?sale=1">Explore the deals ↗</a></div><section class="hero" aria-labelledby="hero-title"><div class="hero-content"><div class="eyebrow">The spring tech edit / 2026</div><h1 id="hero-title" data-experiment-target="hero-headline">Big on possibility.<br><em>Small on price.</em></h1><p id="hero-description">Fresh tech. Better everyday.<br>Save on the things that move you forward.</p><a class="btn lime" href="#/shop?sale=1" id="hero-cta" data-promotion="spring-tech-sale">Find your upgrade ${icon('arrow')}</a><div class="hero-note">Good things don’t stay in stock for long.</div></div><div class="hero-number"><b>01</b> — THE SPRING EDIT</div></section><div class="container"><div class="benefits"><div class="benefit">${icon('truck')}<div><strong>Good tech, delivered free</strong><small>On orders over $150</small></div></div><div class="benefit">${icon('return')}<div><strong>Room to change your mind</strong><small>30-day easy returns</small></div></div><div class="benefit">${icon('shield')}<div><strong>Shop with a little confidence</strong><small>2-year product warranty</small></div></div><div class="benefit">${icon('bolt')}<div><strong>A little loyalty goes a long way</strong><small>Earn points with Amp Rewards</small></div></div></div><section class="section"><div class="section-heading"><div><h2>What are you into?</h2><p>Find a little something that feels like you.</p></div><a class="subtle-link" href="#/shop">Explore all tech ${icon('arrow')}</a></div><div class="categories">${categories.map(c=>`<a class="category" href="#/shop?category=${c.id}" data-category="${c.id}"><div class="category-visual" style="background:${c.color}">${icon(c.icon)}</div><strong>${c.name}</strong><small>${c.tag}</small></a>`).join('')}</div></section><section class="section"><div class="section-heading"><div><h2>Good finds. Great prices.</h2><p>The tech everyone’s talking about, for less.</p></div><a class="subtle-link" href="#/shop?sale=1">Shop all offers ${icon('arrow')}</a></div><div class="product-grid">${products.slice(0,4).map(productCard).join('')}</div></section><div class="rewards-banner"><div class="reward-emblem">✳</div><div><div class="eyebrow">Meet Amp Rewards</div><h2>Your good taste deserves a little back.</h2><p>Earn points on every purchase. Turn everyday upgrades into more.</p></div><a class="btn primary" href="#/rewards">Join the good side ${icon('arrow')}</a></div></div>`;}
function shop(params){const cat=params.get('category')||'',q=params.get('q')||'',sort=params.get('sort')||'featured',sale=params.get('sale')==='1';let list=products.filter(p=>(!cat||p.category===cat)&&(!q||`${p.name} ${p.subtitle} ${p.brand} ${p.category}`.toLowerCase().includes(q.toLowerCase()))&&(!sale||p.was>p.price));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);if(sort==='rating')list.sort((a,b)=>b.rating-a.rating);const title=q?`Results for “${esc(q)}”`:categories.find(c=>c.id===cat)?.name|| (sale?'The spring tech sale':'Find your next upgrade');viewTrack(q?'Search Performed':cat?'Category Viewed':'Product List Viewed',q?{query:q,result_count:list.length}:{category:cat||'all',result_count:list.length,sale});return pageShell(title,'Good tech, thoughtfully picked. Find the right fit for your everyday.',`<div class="shop-layout"><aside class="filter-panel" aria-label="Product filters"><h3>Shop by category</h3><a href="#/shop" class="${!cat?'selected':''}">All tech</a>${categories.map(c=>`<a class="${cat===c.id?'selected':''}" href="#/shop?category=${c.id}">${c.name}</a>`).join('')}<label><input type="checkbox" id="sale-filter" ${sale?'checked':''}> Sale offers only</label><div class="demo-note">A little extra off?<br>Use <b>AMP10</b> at checkout.</div></aside><div><div class="shop-toolbar"><span>${list.length} good ${list.length===1?'find':'finds'}</span><label class="visually-hidden" for="sort-select">Sort products</label><select id="sort-select"><option value="featured" ${sort==='featured'?'selected':''}>Sort: Featured</option><option value="low" ${sort==='low'?'selected':''}>Price: Low to high</option><option value="high" ${sort==='high'?'selected':''}>Price: High to low</option><option value="rating" ${sort==='rating'?'selected':''}>Top rated</option></select></div>${list.length?`<div class="product-grid">${list.map(productCard).join('')}</div>`:`<div class="empty-state">${icon('search')}<h2>No matches just yet.</h2><p>Try “laptop”, “wireless”, or a brand like Sonora.</p><a class="btn primary" href="#/shop">Explore all tech</a></div>`}</div></div>`);}
function detail(p){viewTrack('Product Viewed',productProperties(p));return `<div class="container"><div class="breadcrumb"><a href="#/">Home</a> › <a href="#/shop?category=${p.category}">${categories.find(c=>c.id===p.category).name}</a> › ${p.name}</div><section class="product-detail"><div class="detail-visual"><span class="badge save-badge">${p.badge}</span>${art(p.art,p.color)}</div><div class="detail-info"><div class="product-brand">${p.brand}</div><h1>${p.name}</h1><div class="product-subtitle">${p.subtitle}</div><div class="rating"><span class="stars">★★★★★</span> ${p.rating} <span class="review-count">${p.reviews} happy humans</span></div><div class="price-row"><span class="price">${money(p.price)}</span><span class="old-price">${money(p.was)}</span></div><p class="fine-print">You save ${money(p.was-p.price)} · Price includes simulated GST</p><ul>${p.specs.map(s=>`<li>${s}</li>`).join('')}</ul><span class="in-stock">${p.stock>100?'In stock':`Only ${p.stock} in stock`}. Ready for your next chapter.</span><div class="detail-actions"><button class="primary" id="product-add-to-cart" data-action="add" data-id="${p.id}">${icon('cart')} Add to cart · ${money(p.price)}</button><button class="outline" data-action="wish" data-id="${p.id}" aria-label="Save ${p.name} to wishlist">${icon('heart')}</button></div><div class="detail-shipping">${icon('truck')} ${p.price>=150?'Free standard shipping':'Standard shipping $9.95'} · Dispatch in 1–2 business days</div><div class="detail-shipping">${icon('return')} 30-day easy returns. A little peace of mind.</div></div></section><section class="section mb"><div class="section-heading"><h2>A little more your style</h2></div><div class="product-grid">${products.filter(x=>x.id!==p.id).slice(0,4).map(productCard).join('')}</div></section></div>`;}
function orderSummary(action=true){const t=totals(cart,coupon,shipping);return `<aside class="panel summary"><h2>Your good finds</h2><div class="summary-line muted"><span>Subtotal (${cart.reduce((n,x)=>n+x.qty,0)} items)</span><span>${money(t.subtotal)}</span></div>${t.discount?`<div class="summary-line"><span>AMP10 · 10% off</span><span>−${money(t.discount)}</span></div>`:''}<div class="summary-line muted"><span>${shipping==='express'?'Express':'Standard'} delivery</span><span>${t.shipping?money(t.shipping):'On us'}</span></div><div class="summary-line total"><span>Total</span><span>${money(t.total)}</span></div><span class="field-help">AUD · Includes simulated GST</span>${action?`<form id="coupon-form" class="coupon"><label class="visually-hidden" for="coupon-code">Promo code</label><input id="coupon-code" placeholder="Promo code" value="${esc(coupon)}"><button>Apply</button></form><span id="coupon-error" class="error" role="alert"></span><a class="btn primary" id="checkout-cta" href="#/checkout">On to checkout ${icon('arrow')}</a><a class="btn outline" href="#/shop">Keep exploring</a>`:''}<div class="demo-note">${icon('shield')} This is a demo store. Use the supplied test details. No payment will be taken.</div></aside>`;}
function cartPage(){viewTrack('Cart Viewed',{item_count:cart.reduce((n,x)=>n+x.qty,0),...totals(cart,coupon,shipping)});if(!cart.length)return pageShell('Your cart','',empty('cart','Your next good find is waiting.','Let’s fill this space with something you’ll love.','Explore the tech','#/shop'));return pageShell('Your cart','A little closer to your next upgrade.',`<div class="cart-layout"><div class="panel">${cart.map(row=>{const p=findProduct(row.id);return `<div class="cart-item"><a class="thumb" href="#/product/${p.id}">${art(p.art,p.color)}</a><div><div class="product-brand">${p.brand}</div><a href="#/product/${p.id}"><h3>${p.name}</h3></a><div class="product-subtitle">${p.subtitle}</div><div class="quantity"><button data-action="qty" data-id="${p.id}" data-delta="-1" aria-label="Decrease quantity of ${p.name}">−</button><span aria-label="Quantity">${row.qty}</span><button data-action="qty" data-id="${p.id}" data-delta="1" aria-label="Increase quantity of ${p.name}">+</button></div></div><div class="item-end"><span class="price">${money(p.price*row.qty)}</span><button class="text-button" data-action="remove" data-id="${p.id}">Remove</button></div></div>`;}).join('')}<p class="fine-print" style="margin-top:22px;margin-bottom:0">Good choices. You’ll earn ${Math.floor(totals(cart,coupon,shipping).total)} Amp Rewards points with this order.</p></div>${orderSummary()}</div>`);}
function empty(symbol,title,text,cta,href){return `<div class="empty-state">${icon(symbol)}<h2>${title}</h2><p>${text}</p><a class="btn primary" href="${href}">${cta} ${icon('arrow')}</a></div>`;}
function field(name,label,value='',placeholder='',full=false,type='text'){return `<label class="${full?'full':''}" for="${name}">${label}<input id="${name}" name="${name}" type="${type}" value="${esc(value)}" placeholder="${placeholder}" autocomplete="off" aria-describedby="error-${name}" data-private><span id="error-${name}" class="error" role="alert"></span></label>`;}
function checkoutPage(){if(!cart.length)return cartPage();if(!checkout.started){viewTrack('Checkout Started',{item_count:cart.reduce((n,x)=>n+x.qty,0),...totals(cart,coupon,shipping)});checkout.started=true;}const d=checkout.delivery;return pageShell('A good choice. Almost yours.','Just a few details and you’re all set.',`<div class="checkout-step"><b class="${checkout.step===1?'active':''}">1 &nbsp; Delivery</b><span>—</span><b class="${checkout.step===2?'active':''}">2 &nbsp; Payment</b><span>—</span><span>3 &nbsp; All yours</span></div><div class="checkout-layout"><div class="panel checkout-form">${checkout.step===1?`<h2>Where should we send it?</h2><p class="fine-print">Use fictional details for this workshop.</p><button class="text-button mb" data-action="fill-delivery">Fill demo delivery details</button><form id="delivery-form" novalidate><div class="form-grid">${field('firstName','First name',d.firstName)}${field('lastName','Last name',d.lastName)}${field('email','Email',d.email,'you@example.com',true,'email')}${field('address','Street address',d.address,'123 Demo Street',true)}${field('city','Suburb / city',d.city)}${field('postcode','Postcode',d.postcode,'2000')}${field('state','State / region',d.state,'NSW')}${field('country','Country',d.country||'Australia')}</div><h3 style="margin-top:24px;font-size:15px">Make it your delivery</h3><label class="radio-card"><input type="radio" name="shipping" value="standard" ${shipping==='standard'?'checked':''}> Standard · 3–5 business days <strong>${totals(cart,coupon,'standard').shipping?money(9.95):'FREE'}</strong></label><label class="radio-card"><input type="radio" name="shipping" value="express" ${shipping==='express'?'checked':''}> Express · 1–2 business days <strong>$19.95</strong></label><div class="form-actions"><a class="btn outline" href="#/cart">Back to cart</a><button class="primary">Continue to payment ${icon('arrow')}</button></div></form>`:`<h2>A little formality.</h2><p class="fine-print">Demo payment only. Don’t enter real card details.</p><div class="test-cards"><button data-action="test-card" data-mode="success">Fill successful card</button><button data-action="test-card" data-mode="invalid">Fill invalid card</button><button data-action="test-card" data-mode="decline">Fill declined card</button></div><form id="payment-form" novalidate><div class="payment-fields amp-block"><div class="form-grid">${field('cardName','Name on card','','Alex Demo',true)}${field('card','Card number','','4242 4242 4242 4242',true)}${field('expiry','Expiry date','','12/35')}${field('cvv','Security code','','123')}</div></div><span id="error-payment" class="error" role="alert"></span><div class="demo-note">Delivery to ${esc(d.city)}, ${esc(d.postcode)} · ${shipping==='express'?'Express':'Standard'} shipping. <button type="button" class="text-button" data-action="back-delivery">Change</button></div><div class="form-actions"><button type="button" class="outline" data-action="back-delivery">Back to delivery</button><button class="primary" id="place-order" ${checkout.busy?'disabled':''}>Place demo order · ${money(totals(cart,coupon,shipping).total)}</button></div></form>`}</div>${orderSummary(false)}</div>`);}
function successPage(){const order=storage.get(`last-order:${shopKey()}`,null);if(!order)return pageShell('Your orders','',empty('cart','No new order here yet.','Your next great find is a click away.','Explore tech','#/shop'));return `<div class="container"><div class="panel order-success"><div class="success-mark">${icon('check')}</div><div class="eyebrow">A little upgrade is on its way</div><h1 style="margin-top:15px">Good choice. Great feeling.</h1><p>Your demo order <b>${order.id}</b> is confirmed.<br>No payment was taken. That’s the beauty of a workshop.</p>${order.items.map(row=>`<div class="summary-line"><span>${row.qty} × ${findProduct(row.id).name}</span><b>${money(findProduct(row.id).price*row.qty)}</b></div>`).join('')}<div class="summary-line total"><span>Order total</span><b>${money(order.total)}</b></div><p>You earned ${Math.floor(order.total)} Amp Rewards points.</p><a class="btn primary" href="#/shop">Find something else ${icon('arrow')}</a><a class="btn outline" href="#/account">Your orders</a><div class="spacer"></div><h3>How was your experience?</h3><div id="feedback-options">${[1,2,3,4,5].map(n=>`<button class="outline" data-action="feedback" data-rating="${n}" aria-label="Rate ${n} out of 5">${n} ★</button>`).join('')}</div></div></div>`;}
function personaCards(){return `<div class="persona-list">${personas.map(p=>`<button class="persona-card ${identity.userId===p.id?'selected':''}" data-action="login" data-id="${p.id}"><span class="avatar">${p.initials}</span><span class="persona-copy"><strong>${p.name}</strong><small>${p.tier} · ${p.points.toLocaleString()} points · ${p.orders} previous orders</small><small>${p.segment} · Last purchase ${p.last_order_days} days ago</small></span>${icon(identity.userId===p.id?'check':'arrow')}</button>`).join('')}</div>`;}
function accountPage(){viewTrack('Account Viewed',{logged_in:!!identity.userId});if(!activePersona)return pageShell('Hello, good to see you.','Choose a fictional shopper to explore a personalised experience.',`<div class="account-grid"><div class="panel"><h2 style="font-size:22px">Your tech. Your little world.</h2><p class="fine-print">Sign in to see your Amp Rewards, keep your wishlist close, and make your next upgrade feel easy.</p><div class="demo-note">These are demo personas. No password, email or real account is required.</div></div><div class="panel"><h2 style="font-size:21px">Pick your shopper</h2>${personaCards()}</div></div>`);const orders=storage.get('orders',[]).filter(o=>o.owner===identity.userId);return pageShell(`Hi, ${esc(activePersona.name.split(' ')[0])}.`,'Good to have you back.',`<div class="account-grid"><div class="panel account-card"><div class="persona-row"><div class="avatar">${activePersona.initials}</div><div><h3>${activePersona.name}</h3><small>${activePersona.segment}</small></div></div><div class="spacer"></div><span class="tag">${activePersona.tier.toUpperCase()} MEMBER</span><h2 style="margin-top:20px">${(activePersona.points+orders.reduce((n,o)=>n+Math.floor(o.total),0)).toLocaleString()} points</h2><p>A little closer to your next reward.</p><a class="btn outline" href="#/wishlist">Your wishlist ${icon('heart')}</a><button class="text-button" style="display:block;margin-top:20px" data-action="new-user">Sign out</button></div><div class="panel"><h2 style="font-size:23px">Your orders</h2><p class="fine-print">${activePersona.orders} previous demo purchases · Orders placed on this device appear below.</p>${orders.length?orders.slice().reverse().map(o=>`<div class="order-row"><div><b>${o.id}</b><br><small>${new Date(o.time).toLocaleDateString('en-AU')} · ${o.items.map(i=>findProduct(i.id).name).join(', ')}</small></div><div><b>${money(o.total)}</b><br><span class="tag">Confirmed</span></div></div>`).join(''):'<p class="fine-print">No new orders on this device yet. Find your next good thing.</p>'}<a href="#/shop" class="btn primary" style="margin-top:23px">Keep exploring ${icon('arrow')}</a></div></div>`);}
function rewardsPage(){viewTrack('Rewards Viewed',{logged_in:!!activePersona});return pageShell('A little loyalty. A lot to love.','Meet Amp Rewards. Your everyday upgrades, with a little something back.',`<div class="help-grid">${[['Bronze','Your first good find','Free to join. Earn one point for every dollar you spend.'],['Silver','A little more possibility','Earn 2× points, with early access to our next tech edit.'],['Gold','The good stuff, first','Get first access, bonus offers, and even more reasons to upgrade.']].map(([tier,title,text])=>`<div class="panel"><span class="tag">${tier.toUpperCase()}</span><h3 style="margin-top:18px">${title}</h3><p>${text}</p></div>`).join('')}</div><div class="rewards-banner"><div><h2>Good things add up.</h2><p>100 points = $1 towards your next find. ${activePersona?`You’re a ${activePersona.tier} member.`:'Your next chapter starts with a free membership.'}</p></div><a class="btn primary" href="#/account">${activePersona?'See your points':'Choose a demo account'} ${icon('arrow')}</a></div>`);}
function helpPage(){viewTrack('Help Viewed');return pageShell('A little help goes a long way.','Here for the questions, big and small.',`<div class="help-grid"><div class="panel">${icon('truck')}<h3 style="margin-top:20px">Delivery that fits</h3><p>Standard shipping is free over $150, or $9.95 below. Need it sooner? Express is $19.95.</p></div><div class="panel">${icon('return')}<h3 style="margin-top:20px">Change of heart?</h3><p>Our fictional 30-day return policy keeps things simple. There are no real shipments or payments.</p></div><div class="panel">${icon('user')}<h3 style="margin-top:20px">Your little world</h3><p>Demo accounts, carts, wishlists and orders stay in this browser. Choose a shopper to get started.</p><a class="subtle-link" href="#/account">Your account ${icon('arrow')}</a></div></div><div class="prose"><details><summary>How do I try checkout errors?</summary><p>Add a product, go to checkout, fill demo delivery details, and select an invalid or declined test card. Workshop settings (the bottom-left cog) also has timeout and random error modes.</p></details><details><summary>Which payment details should I use?</summary><p>Use 4242 4242 4242 4242 for success, 4000 0000 0000 0002 for a decline, or 1234 for invalid details. Any future expiry and a 3-digit test security code work.</p></details><details><summary>Where is my data stored?</summary><p>Store state stays in browser storage. With an API key saved in workshop settings, events and live replays are sent to your selected Amplitude project. The settings panel and payment fields are excluded from replay.</p></details></div>`);}
function storesPage(){viewTrack('Store Locator Viewed');return pageShell('Good tech. In your neighbourhood.','Drop into one of our fictional stores.',`<div class="help-grid">${[['Sydney CBD','123 George Street, Sydney NSW 2000','Mon–Fri 9am–6pm · Sat–Sun 10am–5pm'],['Melbourne Central','48 Demo Lane, Melbourne VIC 3000','Mon–Fri 9am–7pm · Sat–Sun 10am–5pm'],['Brisbane City','8 Sample Street, Brisbane QLD 4000','Mon–Fri 9am–6pm · Sat–Sun 10am–4pm']].map(([name,address,hours])=>`<div class="panel">${icon('pin')}<h3 style="margin-top:20px">${name}</h3><p>${address}<br>${hours}</p><span class="in-stock">Demo store · no actual location</span></div>`).join('')}</div>`);}
function workshopPage(){return pageShell('Follow your curiosity.','Your Amplitronics practitioner quick-start.',`<article class="prose"><p>This working electronics store is your shared starting point. Technical analytics practitioners can inspect the schema and payloads. Product and design practitioners can shop, diagnose friction, and choose an improvement.</p><h2>Get connected</h2><ol><li>Open the cog at the bottom-left. Paste your <b>Amplitude project API key</b>, choose US or EU, then select <b>Save & connect</b>. The key stays in this browser’s localStorage.</li><li>Analytics, Autocapture, Session Replay, Web Experiment, and Guides & Surveys are enabled by default. Your project needs the relevant products enabled.</li><li>Open <b>Events</b> in the cog to see custom events, automatic events, and upload status. “Local” means no connected SDK; “sent” means Amplitude acknowledged the custom event.</li></ol><div class="station"><h3>1. Walk in a shopper’s shoes</h3><p>Browse a category, search for a product, save a favourite, and add it to your cart. Apply <code>AMP10</code>, then use the demo delivery and successful card buttons to place an order.</p><p><b>Done when:</b> you can find <code>Order Completed</code> in the event inspector and Amplitude’s User Lookup.</p></div><div class="station"><h3>2. Find the friction</h3><p>Start a new anonymous user from the cog. Try the invalid card, declined card, and timeout scenario. Correct the details and complete the order.</p><p><b>Product & design:</b> where did the message help, and where would a shopper leave? <b>Analytics:</b> build a funnel from Product Viewed → Product Added to Cart → Checkout Started → Order Completed, segmented by Checkout Error.</p><p><b>Done when:</b> you can explain one drop-off with both an event and a live replay.</p></div><div class="station"><h3>3. Give your project a history</h3><p>In <b>30-day history</b>, review the generated counts, then send the backlog. Keep this tab open; you can pause and resume. The generator covers the previous 30 complete UTC days, averaging around 200 daily visitors with weekday patterns, campaign spikes and day-to-day variation. The mix of new and returning shoppers changes each day.</p><p>Filter <code>data_source = synthetic</code> for the seeded dataset, or <code>live</code> for real workshop visits. Compare marketing channels, Mobile versus Desktop, and checkout errors over time.</p><p><b>Done when:</b> you have a hypothesis about the rise in mobile checkout failures during the third and fourth weeks.</p></div><div class="station"><h3>4. Try a better experience</h3><p>In Amplitude Web Experiment, use this site URL and target <code>#hero-title</code>, <code>#hero-cta</code>, or <code>#checkout-cta</code>. Create and publish your own variant. Use Order Completed as the conversion event.</p><p>In Guides & Surveys, create a Web guide or survey, target this URL or <code>Product Added to Cart</code>, and publish it. Use <code>#product-add-to-cart</code> as a product-page guide target. The SDK shares Analytics identity automatically.</p><p><b>Done when:</b> a real live visit receives your published experience. Experiments and surveys must be authored in your Amplitude project; past Analytics events do not create recordings or historical experiment assignments.</p></div><h2>Your core event map</h2><p>Page views use <code>[Amplitude] Page Viewed</code>, emitted by Autocapture during live visits. Historical datasets send the same event name and standard Amplitude page properties.</p><table><thead><tr><th>Action</th><th>Custom event</th><th>Useful properties</th></tr></thead><tbody>${[['Browse','Category Viewed / Product Viewed','category, product_id, price'],['Search','Search Performed','query, result_count'],['Choose','Product Added to Cart / Wishlist Updated','quantity, cart_value, action'],['Start checkout','Checkout Started / Checkout Step Completed','subtotal, total, item_count, step'],['Try paying','Payment Submitted / Checkout Error','attempt, error_code, step, field'],['Buy','Order Completed','order_id, total, products, revenue (top-level)'],['Respond','Store Feedback Submitted','rating, context']].map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table><h2>Useful things to know</h2><ul><li>All prices and revenue use AUD. No real order, payment, or email is sent.</li><li>New anonymous user resets the SDK identity and session and opens a fresh local cart. Signing in merges the current cart into the chosen persona’s cart.</li><li>A saved persona persists across reloads. API keys are public ingestion keys; never paste a secret key here.</li><li>Session Replay uses a 100% sampling request for workshop visits, subject to project settings and quotas. Actual recordings require a live browser visit.</li><li>The backlog is synthetic Analytics data. It cannot manufacture Session Replay recordings or genuine native experiment and survey histories.</li><li>The seed is repeatable. Resume retries use the same insert IDs; Amplitude’s event deduplication window is seven days. Do not resume an old partially uploaded run beyond that window.</li></ul><p><a href="./QUICKSTART.md">Download the participant quick-start</a> · <a href="./tracking-plan.csv">Event tracking plan (CSV)</a></p></article>`);}
function render(navigation=false){recordViews=navigation;const {path,params}=routeInfo();renderHeader();let content;if(path==='/')content=home();else if(path==='/shop')content=shop(params);else if(path.startsWith('/product/')){const p=findProduct(path.split('/')[2]);content=p?detail(p):pageShell('Product not found','',empty('search','That one got away.','Explore the rest of our range.','Shop all','#/shop'));}else if(path==='/cart')content=cartPage();else if(path==='/checkout')content=checkoutPage();else if(path==='/confirmation')content=successPage();else if(path==='/account')content=accountPage();else if(path==='/rewards')content=rewardsPage();else if(path==='/help')content=helpPage();else if(path==='/stores')content=storesPage();else if(path==='/wishlist')content=pageShell('Your little wishlist.','Good things worth coming back for.',wishlist.length?`<div class="product-grid mb">${wishlist.map(findProduct).filter(Boolean).map(productCard).join('')}</div>`:empty('heart','Save a little inspiration.','Tap the heart on a product to keep it close.','Find your favourites','#/shop'));else if(path==='/workshop')content=workshopPage();else content=pageShell('A little off the beaten track.','',empty('search','Let’s get you back.','This page is still a possibility.','Back home','#/'));$('#main').innerHTML=content;renderFooter();document.title=pageTitle(path);}
function addToCart(id){const p=findProduct(id);if(!p)return;const row=cart.find(x=>x.id===id);if(row&&row.qty>=Math.min(20,p.stock)){toast('You’ve reached the demo quantity limit.');track('Cart Error',{error_code:'quantity_limit',product_id:id});return;}if(row)row.qty++;else cart.push({id,qty:1});saveShop();checkout.started=false;track('Product Added to Cart',{...productProperties(p),quantity:1,cart_value:totals(cart,coupon,shipping).subtotal});renderHeader();toast(`${p.name} is in your cart.`);}
function updateWish(id){const p=findProduct(id);if(!p)return;const exists=wishlist.includes(id);wishlist=exists?wishlist.filter(x=>x!==id):[...wishlist,id];saveShop();track('Wishlist Updated',{...productProperties(p),action:exists?'removed':'added'});const position=scrollY;render();window.scrollTo(0,position);toast(exists?'Removed from your wishlist.':'A good find, saved for later.');}
function showErrors(errors){for(const [name,message] of Object.entries(errors)){const input=$(`#${name}`);if(input){input.setAttribute('aria-invalid','true');input.addEventListener('input',()=>{input.removeAttribute('aria-invalid');const e=$(`#error-${name}`);if(e)e.textContent='';},{once:true});}const node=$(`#error-${name}`);if(node)node.textContent=message;}const name=Object.keys(errors)[0];$(`#${name}`)?.focus();}
function clearErrors(form){form.querySelectorAll('.error').forEach(el=>el.textContent='');form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));}
async function login(id){const persona=personas.find(p=>p.id===id);if(!persona)return;const anonymousDevice=identity.userId?null:identity.deviceId;const old=identity.userId?[]:[...cart];saveShop();if(identity.userId&&identity.userId!==id)await newAnonymous();identify(persona);activePersona=persona;if(anonymousDevice){const orders=storage.get('orders',[]);let changed=false;for(const order of orders)if(order.owner===anonymousDevice){order.owner=persona.id;changed=true;}if(changed)storage.set('orders',orders);}
readShop();for(const row of old){const found=cart.find(x=>x.id===row.id);if(found)found.qty=Math.min(20,findProduct(row.id).stock,found.qty+row.qty);else cart.push(row);}saveShop();checkout={step:1,delivery:{},attempt:0,busy:false};$('#persona-dialog').close();$('#workshop-dialog').close();go('/account');toast(`Welcome back, ${persona.name.split(' ')[0]}.`);}
async function resetUser(){if(checkout.busy)return toast('Wait for this demo payment to finish.');saveShop();await newAnonymous();activePersona=null;readShop();coupon='';shipping='standard';checkout={step:1,delivery:{},attempt:0,busy:false};$('#persona-dialog').close();if($('#workshop-dialog').open)renderSettings();go('/');toast('New anonymous shopper. Fresh device ID, session, and cart.');}
function openPersonas(){const dialog=$('#persona-dialog');dialog.innerHTML=`<div class="dialog-head"><div><h2 id="persona-title">Meet your demo shoppers</h2><p>Same store. A different perspective.</p></div><button class="close-button" data-action="close-personas" aria-label="Close persona picker">${icon('close')}</button></div><div class="dialog-body">${personaCards()}<button class="outline" style="margin-top:20px" data-action="new-user">Start a new anonymous shopper</button></div>`;dialog.showModal();}
function ensureGenerated(){if(!run)run=makeBacklogRun();if(!generated)generated=generateBacklog(run);return generated;}
function statusMarkup(){return Object.entries(sdkStatus).map(([key,value])=>`<div class="sdk-status"><b>${{analytics:'Analytics',autocapture:'Auto Tracking',replay:'Session Replay',experiment:'Web Experiment',engagement:'Guides & Surveys'}[key]}</b><span data-sdk-status="${key}">${esc(value)}</span></div>`).join('');}
function startSettings(){return `<section class="getting-started"><h3>Start exploring with Amplitude.</h3><p>Connect your own project, shop around, and see the story behind every interaction.</p><div class="getting-started-links"><a class="btn outline" href="https://amplitude.com/docs/data/chrome-extension-debug" target="_blank" rel="noopener noreferrer">Chrome debug extension ↗</a><a class="btn outline" href="https://app.amplitude.com/signup" target="_blank" rel="noopener noreferrer">Sign up for Amplitude ↗</a></div><ol class="getting-started-steps"><li><strong>Install the Chrome debug extension.</strong><span>Open the extension link above and install it in your Chrome browser so you can inspect events as you explore.</span></li><li><strong>Create a project and get its API key.</strong><span>Sign up or sign in to your Amplitude account, set up a new project, and copy its project API key.</span></li><li><strong>Connect your project to this store.</strong><span>Go to <b>Connect</b>, paste the API key, choose your project’s data region, and select <b>Save &amp; connect</b>.</span></li><li><strong>Browse around and follow the events.</strong><span>Explore the store and see what is sent to Amplitude. Use the Chrome extension, this panel’s <b>Events</b> tab, and your Amplitude project to follow along.</span></li><li><strong>Try different kinds of shoppers.</strong><span>Under <b>Shoppers</b>, switch between known users or start a new anonymous user to explore how identity changes the story.</span></li><li><strong>Put checkout through its paces.</strong><span>Play with the controls under <b>Checkout errors</b>, then try purchasing to see errors, drop-offs, and successful retries.</span></li><li><strong>Add a full 30 days of history.</strong><span>Open <b>30-day history</b> and send a realistic backlog of events straight from your browser. You’ll have more activity, journeys, and marketing traffic to explore in Amplitude.</span></li></ol><section class="project-ai-context" aria-labelledby="project-ai-title"><h3 id="project-ai-title">Project-level AI context</h3><p id="project-ai-help">Paste this into your Amplitude project’s AI context to give Global Agent background about the site and its checkout funnel.</p><textarea id="project-ai-context" rows="10" readonly aria-labelledby="project-ai-title" aria-describedby="project-ai-help" spellcheck="false">${esc(PROJECT_AI_CONTEXT)}</textarea><button class="outline" data-action="copy-ai-context">Copy AI context</button><p id="ai-copy-status" class="field-help" role="status" aria-live="polite"></p></section><button class="primary" data-action="settings-tab" data-tab="connect">Go to Connect ${icon('arrow')}</button></section>`;}
function connectSettings(){return `<form id="settings-form"><div class="settings-grid"><label for="api-key">Amplitude project API key<input id="api-key" type="text" placeholder="YOUR_AMPLITUDE_API_KEY" value="${esc(config.apiKey)}" autocomplete="off" spellcheck="false"><span class="field-help">Saved in localStorage on this device. Never enter a secret key.</span></label><label for="region">Data region<select id="region"><option value="US" ${config.region==='US'?'selected':''}>US</option><option value="EU" ${config.region==='EU'?'selected':''}>EU</option></select></label></div><label class="check-row"><input type="checkbox" id="enable-auto" ${config.autocapture?'checked':''}> Auto Tracking · pages, clicks, attribution, frustration, network, web vitals</label><label class="check-row"><input type="checkbox" id="enable-replay" ${config.replay?'checked':''}> Session Replay · request 100% sampling for workshop visits</label><label class="check-row"><input type="checkbox" id="enable-experiment" ${config.experiment?'checked':''}> Web Experiment · load your project’s visual experiment tag</label><label class="check-row"><input type="checkbox" id="enable-engagement" ${config.engagement?'checked':''}> Guides & Surveys · load published experiences from your project</label><div class="demo-note">Saving enables these Amplitude products on this browser and reloads the store. Configure and publish experiments, guides, and surveys in Amplitude. Replay capture and product availability depend on your project settings. Payment fields and this panel are excluded from recording.</div><span id="settings-error" class="error" role="alert"></span><div style="display:flex;gap:12px"><button class="primary" ${uploadBusy?'disabled':''}>Save & connect ${icon('arrow')}</button><button type="button" class="outline" data-action="disconnect" ${uploadBusy?'disabled':''}>Disconnect</button></div></form><div class="status-grid">${statusMarkup()}</div>`;}
function userSettings(){return `<div class="identity-box"><b>Current shopper:</b> ${activePersona?activePersona.name:'Anonymous'}<br><b>Device ID:</b> <code>${esc(identity.deviceId)}</code><br><b>User ID:</b> <code>${esc(identity.userId||'Not signed in')}</code><br><b>Session ID:</b> <code>${identity.sessionId}</code></div><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="primary" data-action="new-user">New anonymous user + session</button><button class="outline" data-action="open-personas">Log in as a known user</button></div><p style="margin-top:18px">New anonymous user creates a fresh device ID and session, and starts with a separate browser cart. Log in to identify that visitor as a known shopper. Choosing a different signed-in persona starts a separate anonymous identity first.</p>${personaCards()}`;}
function scenarioSettings(){return `<h3>Make a little friction visible.</h3><p>Choose a payment outcome, then try checkout. Every error appears beside the relevant field and emits <code>Checkout Error</code>. No real transaction is attempted.</p><div class="scenario-grid">${[['normal','Normal checkout','Successful valid cards. The declined test card always fails.'],['decline','Always decline','A card decline beside the card number field.'],['network','Payment timeout','A temporary payment error with a retry message.'],['random','Random payment errors','A mix of simulated declines and timeouts.']].map(([value,title,description])=>`<label class="scenario-option"><input type="radio" name="error-mode" value="${value}" ${config.errorMode===value?'checked':''}> ${title}<small>${description}</small></label>`).join('')}</div><label for="random-rate">Random error chance: <span id="rate-value">${config.randomRate}%</span><input id="random-rate" type="range" min="5" max="100" step="5" value="${config.randomRate}"></label><div class="demo-note"><b>Invalid card:</b> 1234<br><b>Declined card:</b> 4000 0000 0000 0002<br><b>Successful card:</b> 4242 4242 4242 4242<br>Use any future expiry and a 3-digit test security code. One-click fill buttons are on the payment page.</div><a href="#/shop" class="btn primary" data-action="close-settings">Try it in the store ${icon('arrow')}</a>`;}
function backlogSettings(){const {events,summary}=ensureGenerated();return `<h3>Give your project a little history.</h3><p>One action sends realistic journeys from the previous 30 complete UTC days, averaging around 200 visitors a day. Weekday patterns, campaign spikes and daily variation shape the mix of new and returning shoppers, abandoned carts, errors, recovered checkouts and purchases.</p><div class="metrics"><div class="metric"><b>${Math.round(summary.dailyVisitors/30)}</b><span>AVERAGE DAILY VISITORS · 30 DAYS</span></div><div class="metric"><b>${summary.uniqueUsers.toLocaleString()}</b><span>DISTINCT USERS ACROSS DAYS</span></div><div class="metric"><b>${events.length.toLocaleString()}</b><span>ANALYTICS EVENTS</span></div><div class="metric"><b>${summary.purchases.toLocaleString()}</b><span>SUCCESSFUL ORDERS</span></div></div><p><b>${new Date(run.start).toISOString().slice(0,10)} → ${new Date(run.start+29*86400000).toISOString().slice(0,10)} (UTC)</b><br>Daily visitors: <b>${Math.min(...summary.daily.map(d=>d.visitors))}–${Math.max(...summary.daily.map(d=>d.visitors))}</b> · ${summary.dailyVisitors.toLocaleString()} visitor-days<br>Dataset: <code>${esc(run.seed)}</code> · ${summary.errors.toLocaleString()} payment errors · ${summary.recoveredPurchases} recovered purchases</p><div class="demo-note">Sends synthetic <b>Analytics</b> events to your ${esc(config.region)} project. Historical imports cannot create live replay recordings, native experiment assignments, or Guides & Surveys delivery history. Use live visits for those. The planted mobile checkout issue appears on days 18–24.<br><br>Small batches and automatic retries respect API limits. Keep this tab open; uploads may take several minutes. Resume the same dataset within 7 days to stay within Amplitude’s deduplication window.</div><div class="progress-label"><span id="upload-count">${run.cursor.toLocaleString()} / ${events.length.toLocaleString()} events acknowledged</span><b id="upload-percent">${Math.floor(run.cursor/events.length*100)}%</b></div><progress id="upload-progress" max="${events.length}" value="${run.cursor}" aria-label="Historical event upload progress"></progress><div id="upload-message" class="progress-info" role="status">${esc(backlogMessage||(run.version<3?'This saved dataset uses the previous traffic model. Resume preserves its original events; choose New dataset for varied daily traffic.':run.cursor===events.length?'Completed. All events acknowledged by Amplitude.':!config.apiKey?'Connect an API key first.':run.cursor?'Ready to resume from the saved checkpoint.':'Ready to send. Existing project data will stay in place.'))}</div><div class="backlog-actions"><button class="primary" data-action="upload" id="upload-button" ${!config.apiKey||uploadBusy||run.cursor===events.length?'disabled':''}>${run.cursor?'Resume upload':'Send 30-day backlog'} ${icon('arrow')}</button><button class="outline" data-action="pause-upload" id="pause-upload" ${!uploadBusy?'disabled':''}>Pause</button></div><div style="display:flex;gap:18px;flex-wrap:wrap;margin-top:20px"><button class="text-button" data-action="export-backlog">Download event dataset (JSON)</button><button class="text-button" data-action="new-dataset" ${uploadBusy?'disabled':''}>New dataset (adds more users)</button></div>`;}
function eventsSettings(){return `<h3>See the store’s own work.</h3><p>Custom events show their upload result. Automatic events are observed before upload; confirm those in Amplitude. “Local” events are for inspection and are not sent retroactively after connecting.</p><div class="event-toolbar"><label><input type="checkbox" id="show-auto" ${showAuto?'checked':''}> Include automatic events</label><div><button class="outline" data-action="export-log">Export log</button><button class="outline" data-action="clear-log">Clear view</button></div></div><div class="event-list" id="event-list">${eventMarkup()}</div>`;}
function eventMarkup(){const list=eventLog.filter(e=>showAuto||!e.event_type?.startsWith('[Amplitude]'));return list.length?list.slice(0,70).map(e=>`<details class="event-item"><summary>${esc(e.event_type)}<span>${new Date(e.loggedAt).toLocaleTimeString()} · ${esc(e.status)}</span></summary><pre>${esc(JSON.stringify({device_id:e.device_id,user_id:e.user_id,session_id:e.session_id,event_properties:e.event_properties,...(e.revenue!==undefined?{revenue:e.revenue,currency:e.currency}:{})},null,2))}</pre></details>`).join(''):'<p class="fine-print">No events in this view. Try shopping and come back.</p>';}
function renderSettings(){const dialog=$('#workshop-dialog');const content={start:startSettings,connect:connectSettings,users:userSettings,scenarios:scenarioSettings,backlog:backlogSettings,events:eventsSettings}[settingsTab]();dialog.innerHTML=`<div class="dialog-head"><div><h2 id="settings-title">Behind the good tech.</h2><p>Your Amplitronics workshop controls</p></div><button class="close-button" data-action="close-settings" aria-label="Close workshop settings">${icon('close')}</button></div><div class="dialog-tabs" role="navigation" aria-label="Workshop settings sections">${[['start','Start here'],['connect','Connect'],['users','Shoppers'],['scenarios','Checkout errors'],['backlog','30-day history'],['events','Events']].map(([id,name])=>`<button data-action="settings-tab" data-tab="${id}" class="${settingsTab===id?'active':''}" aria-current="${settingsTab===id?'page':'false'}">${name}</button>`).join('')}</div><div class="dialog-body">${content}</div>`;}
function openSettings(){renderSettings();$('#workshop-dialog').showModal();}
function download(name,data,type='application/json'){const blob=new Blob([data],{type});const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(href),1000);}
async function startUpload(){if(uploadBusy||!config.apiKey)return;const fingerprint=await projectFingerprint(config.apiKey,config.region);if(run.project&&run.project!==fingerprint){if(!saveBacklogRun(storage,run)){backlogMessage='Cannot save the current project’s progress. Free browser storage and try again.';renderSettings();return;}run=selectBacklogRun(storage,fingerprint,()=>makeBacklogRun(fingerprint));generated=null;}const {events}=ensureGenerated();if(run.cursor===events.length)return;if(run.startedAt&&Date.now()-run.startedAt>7*86400000&&run.cursor>0){backlogMessage='This partial run is older than the seven-day deduplication window. Create a new dataset to avoid ambiguous retries.';renderSettings();return;}run.project=fingerprint;run.startedAt||=Date.now();if(!saveBacklogRun(storage,run)){backlogMessage='Browser storage is full or unavailable. Upload stopped because a safe resume checkpoint cannot be saved.';renderSettings();return;}uploadController=new AbortController();uploadBusy=true;backlogMessage='Sending to Amplitude… Keep this tab open.';renderSettings();const update=(cursor,total)=>{if($('#upload-progress')){$('#upload-progress').value=cursor;$('#upload-count').textContent=`${cursor.toLocaleString()} / ${total.toLocaleString()} events acknowledged`;$('#upload-percent').textContent=`${Math.floor(cursor/total*100)}%`;}if($('#upload-message'))$('#upload-message').textContent=backlogMessage;};try{await uploadBacklog(events,run,{apiKey:config.apiKey,region:config.region,signal:uploadController.signal,save:r=>{if(!saveBacklogRun(storage,r))throw new Error('Cannot save upload checkpoint. Free browser storage and resume.');},onProgress:(cursor,total)=>{backlogMessage='Sending to Amplitude… Keep this tab open.';update(cursor,total);},onRetry:message=>{backlogMessage=message;update(run.cursor,events.length);}});backlogMessage='Complete. Every event has been acknowledged by Amplitude.';toast('Your 30-day history is in Amplitude.');}catch(error){backlogMessage=error.name==='AbortError'?'Paused. You can resume from the saved checkpoint.':error.message;}finally{uploadBusy=false;uploadController=null;if($('#workshop-dialog').open&&settingsTab==='backlog')renderSettings();}}
document.addEventListener('click',async event=>{
 if(event.target.closest('.skip-link')){event.preventDefault();$('#main').focus();return;}
 const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id;
 if(action==='add')addToCart(id);
 else if(action==='wish')updateWish(id);
 else if(action==='qty'){const row=cart.find(x=>x.id===id),p=findProduct(id);if(!row)return;const delta=Number(target.dataset.delta);if(delta>0&&row.qty>=Math.min(20,p.stock))return toast('You’ve reached the demo quantity limit.');row.qty+=delta;if(row.qty<=0)cart=cart.filter(x=>x.id!==id);saveShop();checkout.started=false;track(delta>0?'Product Added to Cart':'Product Removed from Cart',{...productProperties(p),quantity:1,cart_value:totals(cart,coupon,shipping).subtotal});render();}
 else if(action==='remove'){const row=cart.find(x=>x.id===id);cart=cart.filter(x=>x.id!==id);saveShop();checkout.started=false;track('Product Removed from Cart',{...productProperties(findProduct(id)),quantity:row?.qty||1});render();}
 else if(action==='open-personas'){if($('#workshop-dialog').open)$('#workshop-dialog').close();openPersonas();}
 else if(action==='close-personas')$('#persona-dialog').close();
 else if(action==='login'){if(checkout.busy)return toast('Wait for this demo payment to finish.');if(identity.userId===id){$('#persona-dialog').close();$('#workshop-dialog').close();go('/account');return;}await login(id);}
 else if(action==='new-user')await resetUser();
 else if(action==='fill-delivery'){const values={firstName:'Alex',lastName:'Demo',email:'alex@example.com',address:'123 Demo Street',city:'Sydney',postcode:'2000',state:'NSW',country:'Australia'};for(const [name,value]of Object.entries(values))$(`#${name}`).value=value;toast('Fictional delivery details filled.');}
 else if(action==='back-delivery'){checkout.step=1;render();}
 else if(action==='test-card'){const values={cardName:'Alex Demo',card:target.dataset.mode==='success'?'4242 4242 4242 4242':target.dataset.mode==='decline'?'4000 0000 0000 0002':'1234',expiry:'12/35',cvv:'123'};for(const [name,value]of Object.entries(values))$(`#${name}`).value=value;clearErrors($('#payment-form'));}
 else if(action==='feedback'){track('Store Feedback Submitted',{rating:Number(target.dataset.rating),context:'post_purchase'});$('#feedback-options').innerHTML='<p>Thanks for sharing a little feedback.</p>';toast('Thanks. Your feedback helps us make good things better.');}
 else if(action==='close-settings')$('#workshop-dialog').close();
 else if(action==='settings-tab'){settingsTab=target.dataset.tab;renderSettings();}
 else if(action==='copy-ai-context'){const field=$('#project-ai-context'),status=$('#ai-copy-status');field.focus();field.select();let copied=false;try{copied=document.execCommand('copy');}catch{}if(!copied&&navigator.clipboard){try{await Promise.race([navigator.clipboard.writeText(PROJECT_AI_CONTEXT),new Promise((_,reject)=>setTimeout(()=>reject(new Error('Clipboard unavailable')),1500))]);copied=true;}catch{}}status.textContent=copied?'AI context copied. Paste it into your Amplitude project.':'The context is selected. Press Ctrl+C (Windows) or ⌘C (Mac), then paste it into your Amplitude project.';}
 else if(action==='disconnect'){if(uploadBusy)return;config.apiKey='';storage.set('config',config);location.reload();}
 else if(action==='upload')await startUpload();
 else if(action==='pause-upload')uploadController?.abort();
 else if(action==='new-dataset'){run=makeBacklogRun();generated=null;backlogMessage='New dataset ready. Sending it adds a separate population of synthetic users.';saveBacklogRun(storage,run);renderSettings();}
 else if(action==='export-backlog'){const {events,summary}=ensureGenerated();download(`amplitronics-${run.seed}.json`,JSON.stringify({recipe:{version:run.version,siteUrl:run.siteUrl,seed:run.seed,start:run.start,days:run.days,usersPerDay:run.usersPerDay},summary,events},null,2));}
 else if(action==='export-log')download('amplitronics-event-log.json',JSON.stringify(eventLog,null,2));
 else if(action==='clear-log'){eventLog.length=0;$('#event-list').innerHTML=eventMarkup();}
});
document.addEventListener('change',event=>{
 if(event.target.id==='sort-select'){const {params}=routeInfo();params.set('sort',event.target.value);track('Product List Sorted',{sort:event.target.value});go(`/shop?${params}`);}
 else if(event.target.id==='sale-filter'){const {params}=routeInfo();if(event.target.checked)params.set('sale','1');else params.delete('sale');go(`/shop?${params}`);}
 else if(event.target.name==='shipping'){const form=$('#delivery-form');checkout.delivery=Object.fromEntries(new FormData(form));shipping=event.target.value;track('Shipping Method Selected',{shipping_method:shipping});render();}
 else if(event.target.name==='error-mode'){config.errorMode=event.target.value;storage.set('config',config);toast('Checkout scenario saved.');}
 else if(event.target.id==='show-auto'){showAuto=event.target.checked;$('#event-list').innerHTML=eventMarkup();}
});
document.addEventListener('input',event=>{if(event.target.id==='random-rate'){config.randomRate=Number(event.target.value);$('#rate-value').textContent=`${config.randomRate}%`;storage.set('config',config);}});
document.addEventListener('submit',async event=>{
 event.preventDefault();const form=event.target;
 if(form.id==='search-form'){const q=$('#site-search').value.trim();if(q)go(`/shop?q=${encodeURIComponent(q)}`);else go('/shop');}
 else if(form.id==='coupon-form'){const value=$('#coupon-code').value.trim().toUpperCase();if(value==='AMP10'){coupon=value;saveShop();track('Coupon Applied',{coupon,discount:totals(cart,coupon,shipping).discount});render();toast('A little extra off. AMP10 applied.');}else{$('#coupon-error').textContent='That code isn’t valid. Try AMP10.';track('Coupon Rejected',{reason:'invalid_code'});}}
 else if(form.id==='delivery-form'){
  clearErrors(form);const data=Object.fromEntries(new FormData(form)),errors={};for(const key of ['firstName','lastName','address','city','postcode','state','country'])if(!data[key]?.trim())errors[key]='Add this detail to continue.';
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email||''))errors.email='Enter a valid demo email address.';
  if(data.country?.toLowerCase()==='australia'&&!/^\d{4}$/.test(data.postcode||''))errors.postcode='Enter a 4-digit Australian postcode.';
  if(Object.keys(errors).length){showErrors(errors);for(const field of Object.keys(errors))track('Checkout Error',{error_code:'invalid_delivery',step:'delivery',field});return;}
  checkout.delivery=data;checkout.step=2;track('Checkout Step Completed',{step:'delivery',shipping_method:shipping});render();$('#cardName')?.focus();
 }
 else if(form.id==='payment-form'){
  if(checkout.busy)return;clearErrors(form);checkout.attempt++;const data=Object.fromEntries(new FormData(form));
  track('Payment Submitted',{payment_method:'card',attempt:checkout.attempt,total:totals(cart,coupon,shipping).total});
  const errors=validatePayment(data);if(Object.keys(errors).length){showErrors(errors);for(const field of Object.keys(errors))track('Checkout Error',{error_code:field==='card'?'invalid_card':'invalid_payment_details',step:'payment',field,attempt:checkout.attempt});return;}
  checkout.busy=true;const button=$('#place-order');button.disabled=true;button.textContent='Confirming your good choice…';await new Promise(resolve=>setTimeout(resolve,700));
  const failure=paymentOutcome(data.card,config.errorMode,config.randomRate);checkout.busy=false;
  if(failure){const field=failure==='transaction_declined'?'card':'payment';showErrors({[field]:failure==='transaction_declined'?'This demo card was declined. Try the successful test card.':'The demo payment timed out. Your cart is safe. Please try again.'});track('Checkout Error',{error_code:failure,step:'payment',field,attempt:checkout.attempt});button.disabled=false;button.textContent=`Try demo order again · ${money(totals(cart,coupon,shipping).total)}`;return;}
  const t=totals(cart,coupon,shipping),order={id:`AMP-${uuid().slice(0,8).toUpperCase()}`,owner:identity.userId||identity.deviceId,time:Date.now(),items:cart.map(x=>({...x})),...t};
  const orders=storage.get('orders',[]);orders.push(order);storage.set('orders',orders.slice(-150));storage.set(`last-order:${shopKey()}`,order);
  track('Order Completed',{order_id:order.id,item_count:cart.reduce((n,x)=>n+x.qty,0),...t,currency:'AUD',products:cart.map(x=>({product_id:x.id,quantity:x.qty,price:findProduct(x.id).price}))},{revenue:t.total,currency:'AUD',revenueType:'purchase'});
  cart=[];coupon='';saveShop();checkout={step:1,delivery:{},attempt:0,busy:false};go('/confirmation');
 }
 else if(form.id==='settings-form'){
  if(uploadBusy)return;const key=$('#api-key').value.trim();if(!/^[a-zA-Z0-9_-]{10,128}$/.test(key)){$('#settings-error').textContent='Paste a valid Amplitude project API key, or choose Disconnect to keep events local.';return;}
  if((key!==config.apiKey||$('#region').value!==config.region)&&!saveBacklogRun(storage,run)){$('#settings-error').textContent='Cannot save the current project’s upload progress. Free browser storage and try again.';return;}
  Object.assign(config,{apiKey:key,region:$('#region').value,autocapture:$('#enable-auto').checked,replay:$('#enable-replay').checked,experiment:$('#enable-experiment').checked,engagement:$('#enable-engagement').checked});
  if(storage.set('config',config))location.reload();else $('#settings-error').textContent='Unable to save settings. Allow browser storage, then try again.';
 }
});
$('#config-toggle').innerHTML=icon('cog');$('#config-toggle').addEventListener('click',openSettings);
window.addEventListener('hashchange',()=>{render(true);window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});});
window.addEventListener('telemetry-update',()=>{if(!$('#workshop-dialog').open)return;for(const [key,value] of Object.entries(sdkStatus)){const el=$(`[data-sdk-status="${key}"]`);if(el)el.textContent=value;}if(settingsTab==='events'&&$('#event-list')&&!$('#event-list details[open]'))$('#event-list').innerHTML=eventMarkup();});
window.addEventListener('storage-error',()=>toast('Browser storage is unavailable or full. Your changes may not survive a reload.'));
window.addEventListener('beforeunload',event=>{if(uploadBusy){event.preventDefault();event.returnValue='';}});
window.addEventListener('error',event=>{if(event.message&&!/script error/i.test(event.message))track('Application Error',{error_code:'uncaught_error',message:event.message.slice(0,150)});});
startTelemetry();render(true);
